// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for nt-fetc-owns against the loopback mock server
// Flo: start mock > fetch paths > assert status, body, guards
// I/O: mock responses > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const fetc = @import("nt-fetc-owns.zig"); const mock = @import("te-mock-serv.zig");
const allo = std.testing.allocator;
fn opts() fetc.Opts { return .{ .priv_allo = true, .body_maxz = 1 << 20, .time_mill = 5000 }; }
test "plain GET returns 200 and body" { var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var buf4: [64]u8 = undefined; var rslt = try fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/ok"), opts(), .{}); defer rslt.free(allo); try std.testing.expectEqual(@as(u16, 200), rslt.code); try std.testing.expectEqualStrings("<html>hello</html>", rslt.body); try std.testing.expectEqualStrings("\"v1\"", rslt.etag); try std.testing.expect(std.mem.startsWith(u8, rslt.ctyp, "text/html")); }
test "gzip body is inflated, only gzip is offered" { var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var buf4: [64]u8 = undefined; var rslt = try fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/gz"), opts(), .{}); defer rslt.free(allo); try std.testing.expectEqualStrings("<html>gzipped page</html>", rslt.body); try std.testing.expect(std.ascii.findIgnoreCase(srv2.hdrzLast(), "accept-encoding: gzip\r\n") != null); }
test "conditional GET gives 304 with empty body" { var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var buf4: [64]u8 = undefined; var rslt = try fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/cond"), opts(), .{ .etag = "\"v1\"" }); defer rslt.free(allo); try std.testing.expectEqual(@as(u16, 304), rslt.code); try std.testing.expectEqual(@as(usize, 0), rslt.body.len); var res2 = try fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/cond"), opts(), .{}); defer res2.free(allo); try std.testing.expectEqual(@as(u16, 200), res2.code); }
test "redirect is followed by hand, final url kept" { var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var buf4: [64]u8 = undefined; var rslt = try fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/redir"), opts(), .{}); defer rslt.free(allo); try std.testing.expectEqual(@as(u16, 200), rslt.code); try std.testing.expect(std.mem.endsWith(u8, rslt.finl, "/ok")); }
test "redirect loop refused" { var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var buf4: [64]u8 = undefined; try std.testing.expectError(error.RedirectLoop, fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/loop"), opts(), .{})); }
test "redirect to metadata ip refused even when the first hop is allowed" { var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var buf4: [64]u8 = undefined; var gate = opts(); gate.priv_allo = false; try std.testing.expectError(error.BlockedHost, fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/ok"), gate, .{})); }
test "oversize body refused, gzip bomb refused" { var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var buf4: [64]u8 = undefined; try std.testing.expectError(error.TooBig, fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/big"), opts(), .{})); try std.testing.expectError(error.TooBig, fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/bomb"), opts(), .{})); }
test "non-text refused before the body is read" { var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var buf4: [64]u8 = undefined; try std.testing.expectError(error.NotText, fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/img"), opts(), .{})); }
test "status codes pass through: 403 body, 429 retry-after, 404" { var srv2: mock.Mock = undefined; try srv2.sta2(std.testing.io); defer srv2.halt(); var buf4: [64]u8 = undefined; var one2 = try fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/e403"), opts(), .{}); defer one2.free(allo); try std.testing.expectEqual(@as(u16, 403), one2.code); var two2 = try fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/e429"), opts(), .{}); defer two2.free(allo); try std.testing.expectEqual(@as(u16, 429), two2.code); try std.testing.expectEqual(@as(u32, 7), two2.retr); var triz = try fetc.fetcGetz(allo, std.testing.io, srv2.urlzOfzz(&buf4, "/nope"), opts(), .{}); defer triz.free(allo); try std.testing.expectEqual(@as(u16, 404), triz.code); }
test "bad urls refused before any network" { try std.testing.expectError(error.BadUrl, fetc.fetcGetz(allo, std.testing.io, "ftp://a.com/", opts(), .{})); try std.testing.expectError(error.BlockedHost, fetc.fetcGetz(allo, std.testing.io, "http://169.254.169.254/latest", .{}, .{})); try std.testing.expectError(error.BlockedHost, fetc.fetcGetz(allo, std.testing.io, "http://localhost:1/", .{}, .{})); }
